example_item.example_item_data:
folder = tempname();
mkdir(folder);
source = fullfile(folder, 'notes.txt');
filewrite(source, repmat(sprintf('line\n'), 1, 100));
packed = gzip(source)
filenames = gunzip(packed, fullfile(folder, 'out'))
isequal(fileread(filenames{1}), fileread(source))
rmdir(folder, 's');
